  ('john-lennon', 'John Lennon', 'solo', 2, '1940–1980', 'Vokal, Gitar, Piano', 'Liverpool, Inggris', 'Rock / Pop', '', 'Vokalis dan gitaris ritme The Beatles. John melanjutkan karier solonya dengan Plastic Ono Band dan merilis Imagine pada 1971.', 'Imagine, Plastic Ono Band, Double Fantasy.', array['Solo & Ono Band', 'Apple Records']::text[], null, 'JL'),
  ('paul-mccartney', 'Paul McCartney', 'solo', 3, '1942–Sekarang', 'Bass, Vokal, Multi-instrumentalis', 'Liverpool, Inggris', 'Rock / Pop', '', 'Bassis, vokalis, dan salah satu penulis lagu utama The Beatles. Ia memulai diskografi solonya dengan McCartney sebelum membentuk Wings.', 'McCartney, Ram, Band on the Run (Wings).', array['Wings Era', 'MPL Communications']::text[], null, 'PM'),
  ('george-harrison', 'George Harrison', 'solo', 4, '1943–2001', 'Gitaris Utama, Sitar, Penulis Lagu', 'Liverpool, Inggris', 'Rock / Folk', '', 'Gitaris utama The Beatles dan penulis Taxman, Something, serta Here Comes the Sun. Karya solonya mencakup All Things Must Pass dan Living in the Material World.', 'All Things Must Pass, Living in the Material World.', array['Dark Horse', 'Triple LP Master']::text[], null, 'GH'),
  ('ringo-starr', 'Ringo Starr', 'solo', 5, '1940–Sekarang', 'Drum, Perkusi, Vokal', 'Liverpool, Inggris', 'Rock / Pop', '', 'Richard Starkey, dikenal sebagai Ringo Starr, adalah drummer The Beatles dan penulis Octopus’s Garden. Album Ringo terbit pada 1973.', 'Ringo (1973), Beaucoups of Blues, Sentimental Journey.', array['All-Starr Band', 'Ludwig Drums']::text[], null, 'RS')
